import org.junit.Test;
import static org.junit.Assert.*;
import java.io.IOException;

public class TextNodeTest {

    @Test
    public void constructorTests() {
        String text = "Hello World";
        assertTrue(new TextNode(text).text().equals(text));
    }

    @Test
    public void nodeNameTests() {
        String text = "Hello World";
        assertEquals("text", new TextNode(text).nodeName());
    }

    @Test
    public void splitTextTests() throws IOException {
        String text = "Hello\nWorld";
        int offset = 5;
        TextNode node1 = new TextNode(text);
        TextNode expected1 = new TextNode(text.substring(0, offset));
        assertEquals(expected1, node1.splitText(offset).clone());
    }

    @Test
    public void getWholeTextTests() {
        String text = "Hello World";
        assertTrue(new TextNode(text).getWholeText().equals(text));
    }

    @Test
    public void isBlankTests() {
        String text = "";
        assertTrue(new TextNode(text).isBlank());
        String whitespaceText = "   ";
        assertTrue(new TextNode(whitespaceText).isBlank());
    }

    @Test
    public void cloneTests() {
        String text = "Hello World";
        TextNode node1 = new TextNode(text);
        TextNode cloned = node1.clone();
        assertEquals(text, cloned.text());
    }

    @Test
    public void fromEncodedTests() {
        String encodedText = "&lt;Hello&gt;";
        assertTrue(TextNode.createFromEncoded(encodedText).text().equals("<Hello>"));
    }

    @Test
    public void normaliseWhitespaceTests() {
        String text = "   ";
        assertEquals("   ", TextNode.normaliseWhitespace(text));
    }

    @Test
    public void stripLeadingWhitespaceTests() {
        String text = "   Hello World";
        assertEquals("  Hello World", TextNode.stripLeadingWhitespace(text));
    }

    @Test
    public void lastCharIsWhitespaceTests() {
        StringBuilder sb = new StringBuilder("abc ");
        assertTrue(TextNode.lastCharIsWhitespace(sb));
    }
}
